<?php $f=$report['filters'];$money=static fn($c)=>number_format($c/100,2,',',' ');$weight=static fn($g)=>number_format($g/1000,3,',',' ');$exportUrl=static fn($type)=>base_url('butchery/pos/report?'.http_build_query(array_merge($f,['export'=>$type])));?>
