<label><span>État du ticket</span><select name="status"><?php foreach([''=>'Tous les états','paid'=>'Encaissés','cancelled'=>'Annulés']as$key=>$label):?><option value="<?=e($key)?>"<?=$f['status']===$key?' selected':''?>><?=e($label)?></option><?php endforeach;?></select></label>
<label class="pos-report-query"><span>Ticket, client ou vendeur</span><input type="search" name="q" value="<?=e($f['q'])?>" maxlength="180" placeholder="Rechercher dans les ventes…"></label><button type="submit" class="btn-primary"><i class="bi bi-funnel" aria-hidden="true"></i> Appliquer les filtres</button><a class="btn-secondary" href="<?=e(base_url('butchery/pos/report'))?>">Réinitialiser</a></form>
<div class="pos-report-export"><div><strong><?=count($report['tickets'])?> ticket(s) dans la sélection</strong><p>Les exports reprennent les filtres appliqués ci-dessus, toutes pages confondues.</p></div><div><a class="btn-secondary" href="<?=e($exportUrl('xlsx'))?>" data-ajax="false"><i class="bi bi-file-earmark-excel" aria-hidden="true"></i> Exporter Excel</a><a class="btn-primary" href="<?=e($exportUrl('pdf'))?>" data-ajax="false"><i class="bi bi-file-earmark-pdf" aria-hidden="true"></i> Exporter PDF</a></div></div>
