<h3>Tickets de la sélection</h3><div class="table-responsive slaughter-table-wrap"><table class="enterprise-table" data-searchable="false" aria-label="Tickets du rapport de ventes"><thead><tr><?php foreach(['Ticket / date','Comptoir','Client / vendeur','Devise','Total','Paiement','Poids (kg)','État']as$header):?><th scope="col"><?=e($header)?></th><?php endforeach;?></tr></thead><tbody><?php foreach($report['tickets']as$t):?><tr><td data-order="<?=e($t['sold_at'])?>"><a href="<?=e(base_url('butchery/pos/tickets/'.$t['id']))?>" target="_blank" rel="noopener" data-ajax="false"><?=e($t['ticket_number'])?></a><br><?=e(date('d/m/Y H:i',strtotime($t['sold_at'])))?></td><td><?=e($t['counter_name'])?></td><td><?=e($t['customer_name'])?><br><?=e($t['cashier_name'])?></td><td><?=e($t['currency'])?></td><td class="num" data-order="<?=e($t['total'])?>"><?=e(number_format((float)$t['total'],2,',',' '))?></td><td><?=e($report['methods'][$t['payment_method']])?></td><td class="num" data-order="<?=e($t['quantity_kg'])?>"><?=e(number_format((float)$t['quantity_kg'],3,',',' '))?></td><td><span class="ui-status ui-status--<?=$t['status']==='paid'?'success':'danger'?>"><?=$t['status']==='paid'?'Encaissé':'Annulé'?></span></td></tr><?php endforeach;?></tbody></table></div>
<details class="pos-report-breakdown"><summary>Ventes par article · <?=count($report['articles'])?> ligne(s)</summary><div class="table-responsive"><table class="enterprise-table" data-searchable="false" aria-label="Ventes par article"><thead><tr><th>Article</th><th>Devise</th><th>Poids vendu (kg)</th><th>Pièces vendues</th><th>Tickets</th><th>Montant vendu</th></tr></thead><tbody><?php foreach($report['articles']as$a):?><tr><td><?=e($a['name'])?></td><td><?=e($a['currency'])?></td><td class="num" data-order="<?=e($a['grams']/1000)?>"><?=$weight($a['grams'])?></td><td class="num" data-order="<?=e((int)($a['pieces']??0))?>"><?=($a['pieces']??null)===null?'—':e(number_format($a['pieces'],0,',',' '))?></td><td><?=e($a['count'])?></td><td class="num" data-order="<?=e($a['cents']/100)?>"><?=$money($a['cents'])?></td></tr><?php endforeach;?></tbody></table></div></details>
<details class="pos-report-breakdown"><summary>Répartition par paiement · <?=count($report['payments'])?> ligne(s)</summary><div class="table-responsive"><table class="enterprise-table" data-searchable="false" aria-label="Répartition des paiements"><thead><tr><th>Devise</th><th>Paiement</th><th>Tickets encaissés</th><th>Montant vendu</th></tr></thead><tbody><?php foreach($report['payments']as$p):?><tr><td><?=e($p['currency'])?></td><td><?=e($p['method'])?></td><td><?=e($p['count'])?></td><td class="num" data-order="<?=e($p['cents']/100)?>"><?=$money($p['cents'])?></td></tr><?php endforeach;?></tbody></table></div></details>
